#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]), ans(v[3]); int n; in >> n; multiset<pair<int,int>> e; for (int i = 0; i < n - 1; i++) { int a, b; in >> a >> b; e.insert({min(a, b), max(a, b)}); } int want, t; ans >> want; if (!(out >> t) || t != want) return 1; for (int i = 0; i < t; i++) { int a, b, x, y; if (!(out >> a >> b >> x >> y)) return 1; auto it = e.find({min(a, b), max(a, b)}); if (it == e.end()) return 1; e.erase(it); if (x == y || x < 1 || y < 1 || x > n || y > n) return 1; e.insert({min(x, y), max(x, y)}); } vector<int> p(n + 1); iota(p.begin(), p.end(), 0); function<int(int)> f = [&](int x) { return p[x] == x ? x : p[x] = f(p[x]); }; for (auto [a, b] : e) { if (f(a) == f(b)) return 1; p[f(a)] = f(b); } return 0; }
